        heading: '4. 電力と発熱量',
        body: `電気がどれだけのエネルギーを消費するかを「電力」、その熱への変換量を「発熱量」という。

─────────────────────────────
【電力の計算式】
　P（電力・単位W）＝ V（電圧）× I（電流）
　　　　　　　　　 ＝ I² × R （オームの法則を使うと）
　　　　　　　　　 ＝ V² ÷ R
─────────────────────────────

例）100V・5Aの電気ストーブの電力は？
　P ＝ 100 × 5 ＝ 500W

─────────────────────────────
【発熱量の計算式（ジュールの法則）】
　Q（発熱量・単位J）＝ P × t（時間・秒）
　　　　　　　　　　 ＝ V × I × t
─────────────────────────────

例）500Wの電気ストーブを10分（＝600秒）使用したときの発熱量は？
　Q ＝ 500 × 600 ＝ 300,000J ＝ 300kJ

■ kWh（キロワット時）の計算
電力量（電気代の計算に使う）の単位。
　電力量（Wh）＝ 電力（W）× 時間（h）
　1kWh ＝ 1000W × 1時間 ＝ 3,600,000J ＝ 3600kJ

例）1000W（1kW）のドライヤーを1時間使用 → 1kWh
　電気代が1kWhあたり30円ならば → 1kWh × 30円 ＝ 30円

★ ポイント：同じ電圧（100V）で使用する場合、電力の大きい電化製品ほど抵抗が小さい（P ＝ V²÷R より）。「1000Wの電化製品の方が500Wより抵抗が小さい」ことを意識する。

⚠ 注意：「電力」と「電力量」は別物。電力はW（ワット）、電力量はWh（ワット時）またはJ（ジュール）。`,
