        body: `入試最難関レベルの回路問題を体系的に解く手順を習得しよう。

■ 複合回路を解く手順
　STEP1：回路図を見て直列部分と並列部分を整理する
　STEP2：並列部分の合成抵抗を先に求める（逆数公式）
　STEP3：全体を直列回路として扱い、合成抵抗と全電流を計算する
　STEP4：各素子の電圧・電流をオームの法則で求める

■ 未知の抵抗を求める問題

例）電源電圧24V、R₁（既知）＝8Ω に対して直列に未知の抵抗R₂が接続されている。電流計が1.5Aを示したとき、R₂を求めよ。

【解答】
全体の合成抵抗 R ＝ V ÷ I ＝ 24 ÷ 1.5 ＝ 16Ω
R₂ ＝ R ー R₁ ＝ 16 ー 8 ＝ 8Ω

■ 電流計・電圧計の内部抵抗が問題になるケース
理想的な電流計は内部抵抗ゼロ（電圧降下なし）、理想的な電圧計は内部抵抗無限大（電流が流れない）。しかし高校物理・難関中学では内部抵抗を考慮する問題が出る。

■ 電流計の内部抵抗が r のとき：
　電流計と測定対象が直列になるため、実際の電流は「V ÷ (R ＋ r)」となり、真の電流より小さくなる。

■ 電圧計の内部抵抗が R_V のとき：
　電圧計と測定対象が並列になるため、合成抵抗が下がり、実際の電流が増える→測定値に誤差が生じる。

★ 入試トラップ例：回路に電流計を入れると回路の合成抵抗が変化する。「電流計を入れる前と後で電球の明るさが変わる」という問題では、電流計の内部抵抗の影響を考える。

⚠ 注意：電流計は回路に直列に、電圧計は測定したい部分に並列に接続する。逆にすると電流計が壊れる（内部抵抗がほぼゼロのため、大電流が流れる）危険がある。`,
