        body: `酸とアルカリの性質を正確に覚え、中和反応の計算ができるようにしよう。

─────────────────────────────
【酸の性質】
■ 酸：水溶液中で水素イオン（H⁺）を出す物質
・酸の例：塩酸（HCl）・硫酸（H₂SO₄）・酢酸（CH₃COOH）・炭酸（H₂CO₃）
・性質：青色リトマス紙を赤に変える、BTB液を黄色にする、pH＜7
─────────────────────────────

─────────────────────────────
【アルカリの性質】
■ アルカリ：水溶液中で水酸化物イオン（OH⁻）を出す物質
・アルカリの例：水酸化ナトリウム（NaOH）・水酸化カリウム（KOH）・アンモニア（NH₃）・石灰水（Ca(OH)₂）
・性質：赤色リトマス紙を青に変える、BTB液を青色にする、pH＞7
─────────────────────────────

■ 中和反応
　酸 ＋ アルカリ → 塩（えん）＋ 水

　代表的な中和反応：
　HCl ＋ NaOH → NaCl ＋ H₂O（塩酸＋水酸化ナトリウム）
　H₂SO₄ ＋ 2NaOH → Na₂SO₄ ＋ 2H₂O

■ pH（ペーハー）の読み方
・pH ＝ 7 → 中性（純水）
・pH ＜ 7 → 酸性（数が小さいほど強い酸）
・pH ＞ 7 → アルカリ性（数が大きいほど強いアルカリ）

─────────────────────────────
【指示薬まとめ表】
　指示薬　　　 酸性　　 中性　　 アルカリ性
青リトマス紙　 赤　　　 変化なし 変化なし
赤リトマス紙　 変化なし 変化なし 青
BTB液　　　　 黄　　　 緑　　　 青
フェノールフタレイン 無色 無色　  赤
─────────────────────────────

★ ポイント：「塩」は「えん」と読む。塩（food salt）の食塩（NaCl）も塩の一種だが、全ての塩が食塩ではない。Na₂SO₄（硫酸ナトリウム）や CuSO₄（硫酸銅）なども塩。

⚠ 注意：フェノールフタレインはアルカリ性のときだけ赤く変わる（酸性・中性では無色のまま）。BTB液は中性で「緑」になるのを正確に覚えること。`,
