        body: `電気分解とイオンは中学理科の中でも難易度が高いテーマ。体系的に理解しよう。

■ イオンとは
原子が電子を得たり失ったりして電荷を帯びたもの。

■ 陽イオン（＋の電荷）：電子を失った原子
　Na → Na⁺ ＋ e⁻（ナトリウムイオン）
　Mg → Mg²⁺ ＋ 2e⁻（マグネシウムイオン）
　H → H⁺ ＋ e⁻（水素イオン）

■ 陰イオン（－の電荷）：電子を得た原子
　Cl ＋ e⁻ → Cl⁻（塩化物イオン）
　O ＋ 2e⁻ → O²⁻（酸化物イオン）
　SO₄ ＋ 2e⁻ → SO₄²⁻（硫酸イオン）

─────────────────────────────
【水の電気分解】
2H₂O → 2H₂ ＋ O₂
・陰極（マイナス極）：水素H₂が発生（体積：2）
・陽極（プラス極）：酸素O₂が発生（体積：1）
★ 水素：酸素 ＝ 2：1（体積比）
─────────────────────────────

─────────────────────────────
【塩化銅（CuCl₂）水溶液の電気分解】
CuCl₂ → Cu²⁺ ＋ 2Cl⁻
・陰極：銅Cu が析出（赤色の固体）
・陽極：塩素Cl₂ が発生（刺激臭のある黄緑色の気体）
─────────────────────────────

■ 電解質と非電解質
・電解質：水に溶かすとイオンに分かれ（電離）、電気を通す物質。例）食塩・塩酸・水酸化ナトリウム
・非電解質：水に溶かしてもイオンにならず、電気を通さない物質。例）砂糖・エタノール・デンプン

★ 入試トラップ：「塩酸は酸性だが、砂糖水は中性なのにどちらも水溶液」→ 電気を通すかどうかは「酸性かどうか」ではなく「イオンが生じるかどうか」で決まる。砂糖水は中性だが電気を通さない。

⚠ 注意：水の電気分解では純水だけでは電気を通しにくいため、少量の水酸化ナトリウムや硫酸を加えて導電性を上げる。この添加物自体は反応しない（触媒的役割）ことを理解しておく。`,
