        heading: '1. 力の種類と合成',
        body: `力とは物体の形を変えたり、運動の状態を変えたりする作用のこと。まず力の種類と合成方法を理解しよう。

─────────────────────────────
【主な力の種類】
重力　　：地球が物体を引く力（鉛直下向き）
弾性力　：バネや輪ゴムが元に戻ろうとする力
摩擦力　：物体の動きを妨げる力（接触面に平行）
垂直抗力：接触面から物体を押し返す力（接触面に垂直）
磁力　　：磁石が引き合ったり反発したりする力
静電気力：帯電体どうしが引き合ったり反発したりする力
─────────────────────────────

■ 力の単位：ニュートン（N）
　地球上では質量100gの物体に働く重力がほぼ1N
　質量m（kg）の物体に働く重力：F ＝ m × 9.8（≒10）N

■ 力の合成（合力）
2つの力を1つの力に置き換えることを合成という。合成した力を「合力」という。

・同じ向きの力：合力 ＝ F₁ ＋ F₂（力が大きくなる）
・反対向きの力：合力 ＝ F₁ ー F₂（大きい方から差し引く）
・斜め方向の力：平行四辺形の法則を用いる

例）東向き3Nと東向き5Nの合力 → 東向き8N
例）東向き8Nと西向き3Nの合力 → 東向き5N

■ 力のつり合い条件
2つの力がつり合うためには：
① 大きさが等しい
② 向きが逆（正反対）
③ 同一直線上にある

例）机の上に置いた本：重力（下向き）＝ 机の垂直抗力（上向き）でつり合い。

★ ポイント：「力がつり合っている ＝ 物体が静止または等速直線運動している」。加速している物体は力がつり合っていない。

⚠ 注意：「作用・反作用の法則」は2物体間の力で、向きが逆で大きさが等しいが、異なる物体に働く力なので「つり合い」とは異なる。`,
