        heading: '4. 圧力と浮力',
        body: `圧力と浮力は日常生活に密接した概念。計算とともに原理を理解しよう。

─────────────────────────────
【圧力の定義】
　P（圧力・Pa）＝ F（力・N）÷ S（面積・m²）
　1Pa ＝ 1N/m²
─────────────────────────────

例）100Nの力を0.5m²の面積にかけたとき、圧力は？
　P ＝ 100 ÷ 0.5 ＝ 200Pa

■ 大気圧
地球の大気が地表にかける圧力。約1013hPa（＝約100,000Pa）＝ 1atm。
高山に行くほど大気圧は低くなり、水が100℃より低い温度で沸騰する。

■ 水圧の計算
水の中では深さが増すほど上の水の重さが加わる。
　水圧（Pa）＝ 水の密度（1000kg/m³）× 重力加速度（10m/s²）× 深さ（m）
　　　　　　 ＝ 10000 × 深さ（Pa）

例）水深3mでの水圧 ＝ 10000 × 3 ＝ 30,000Pa

─────────────────────────────
【アルキメデスの原理（浮力）】
「液体中の物体には、その物体が押しのけた液体の重さと等しい大きさの浮力が上向きに働く」
　浮力（N）＝ 押しのけた液体の体積（m³）× 液体の密度（kg/m³）× 重力加速度（m/s²）
─────────────────────────────

例）水（密度1000kg/m³）の中に体積500cm³（＝0.0005m³）の物体を完全に沈めたときの浮力
　浮力 ＝ 0.0005 × 1000 × 10 ＝ 5N

■ 物体が浮くか沈むかの判定
・物体の重力 ＜ 浮力 → 浮く（水面に出て均衡する）
・物体の重力 ＝ 浮力 → 水中で静止（中性浮力）
・物体の重力 ＞ 浮力 → 沈む（底に着く）

★ ポイント：物体が完全に水に沈んでいるとき、浮力の大きさは深さに関係しない（体積のみで決まる）。

⚠ 注意：浮力は液体の密度にも依存する。食塩水（密度1200kg/m³程度）では、純水より浮力が大きくなる（卵が浮く有名な実験）。`,
