        body: `遺伝の計算は入試頻出で、比率の問題が多い。メンデルの法則を数式的に理解しよう。

■ 基本用語
・形質（けいしつ）：生物の持つ外見上の特徴（種子の色・形など）
・遺伝子：形質を決める情報の単位（染色体上にある）
・対立遺伝子：1つの形質を決める2つの遺伝子
・優性（顕性）の遺伝子：A（大文字で表す）→ 必ず表れる
・劣性（潜性）の遺伝子：a（小文字で表す）→ AAまたはAaでは隠れる

─────────────────────────────
【遺伝子型と表現型】
AA（ホモ優性）：優性の形質が表れる
Aa（ヘテロ）　：優性の形質が表れる（Aが優性のため）
aa（ホモ劣性）：劣性の形質が表れる
─────────────────────────────

■ F1世代（第一代雑種）
純系の優性（AA）× 純系の劣性（aa）のかけ合わせ
→ F1はすべて Aa（優性の形質のみ表れる）

■ F2世代（第二代）：F1 × F1 のかけ合わせ
　Aa × Aa の遺伝子型の組み合わせ：

　（A or a）×（A or a）
　　AA : Aa : aA : aa ＝ 1:2:1:1（遺伝子型比）
　　表現型比 → 優性：劣性 ＝ 3：1

★ 表現型の比は必ず「優性：劣性 ＝ 3：1」（F2世代の場合）

■ 自家受粉の代数別比率
F1（Aa）：優性のみ 100%
F2（Aa×Aa）：優性75%：劣性25%（3：1）
F3世代以降も自家受粉を続けると、劣性ホモ（aa）の割合が増加していく。

■ 検定交雑（バッククロス）
表現型が優性の個体（AAかAaか不明）を劣性ホモ（aa）とかけ合わせて遺伝子型を調べる方法。
　・もし AA × aa → 子はすべてAa（優性のみ）
　・もし Aa × aa → 子はAa：aa ＝ 1：1（優性：劣性 ＝ 1：1）

例）エンドウの丸い種子（優性）の植物を aa（しわ）とかけ合わせたら、50粒のうち丸25粒・しわ25粒だった。元の植物の遺伝子型は？
→ 丸：しわ ＝ 1：1 → 元の植物は Aa（ヘテロ）

⚠ 注意：「優性＝数が多い」ではない。Aaという1個体でも優性が表れる。比率の話と個体の遺伝子型の話を混同しないこと。`,
