        heading: '3. 棒の重さ・重心・てんびん',
        body: `実際のてこ（棒）には重さがある。棒の重さを考える問題と、重心・てんびんの考え方を理解しよう。

■ 重心（じゅうしん）
物体全体の重さが1点に集中していると考えられる点。均一な棒の重心は「棒のちょうど真ん中」にある。棒の重さは、この重心の位置にまとめてかかっていると考える。

■ 重さのある棒のつり合い
棒自体の重さを「重心の位置にかかる1つのおもり」として計算に加える。

例）長さ60cm・重さ120gの均一な棒の左端を支点にする。棒の右端（60cm）を上向きの力Fで支えるとき、Fは何gか。
　棒の重さ120gは重心（中央30cm）にかかる。
　右端を支える力Fのモーメント ＝ 棒の重さのモーメント
　F × 60 ＝ 120 × 30 ＝ 3600 → F ＝ 60g

─────────────────────────────
【上皿てんびんの使い方】
① 水平な台に置き、指針が左右に等しくふれるように調節する
② はかりたい物体を左の皿にのせる（右ききの場合）
③ 分銅は重い方から順にのせ、つり合ったら合計する
④ 使い終わったら皿を片方に重ねる
─────────────────────────────

■ てんびんとモーメント
上皿てんびんは支点が中央にあり、左右の腕の長さが等しいてこ。だから「左の皿の重さ ＝ 右の分銅の重さ」で重さがはかれる。

★ ポイント：均一でない棒（太さがちがう棒など）では重心が真ん中にない。「棒を1点で支えて水平につり合う点」が重心。この位置を実験や計算で求める問題が出る。

⚠ 注意：分銅はさびや手あぶらを防ぐため、必ずピンセットでつまむ。指でさわると重さが変わって正確にはかれなくなる。`,
