        heading: '4. 輪軸のしくみと計算',
        body: `輪軸（りんじく）は、半径のちがう2つの輪（車輪）を同じ軸に固定した道具。てこの原理と同じ考え方で計算できる。

■ 輪軸の構造
大きい輪（半径R）と小さい輪（半径r）が同じ軸で回る。井戸のつるべ・ドアノブ・ハンドルなどに利用される。

─────────────────────────────
【輪軸のつり合い】
　（大きい輪にかける力）×（大きい輪の半径）
　　　＝（小さい輪にかかる力）×（小さい輪の半径）
─────────────────────────────

これは軸を支点としたてこのつり合いと全く同じ考え方。半径が「支点からの距離」にあたる。

例）半径30cmの大輪と半径10cmの小輪の輪軸がある。小輪に60gのおもりをつるした。大輪に何gの力をかけるとつり合うか。
　x × 30 ＝ 60 × 10 ＝ 600 → x ＝ 20g

■ 輪軸で得をするしくみ
大きい輪に力を加えると、小さい輪では大きな力が出せる（半径の比だけ力が拡大される）。ただし、大きい輪を回す距離は長くなる（仕事の原理）。

例）上の輪軸で、大輪を1回転（円周＝2×3.14×30 ＝ 約188cm）回すと、小輪も1回転（円周＝2×3.14×10 ＝ 約63cm）で、おもりは約63cm持ち上がる。
　力は3分の1（20g で 60g を持ち上げる）だが、動かす距離は3倍になっている。

★ ポイント：輪軸は「大きい輪＝力点、小さい輪＝作用点、軸＝支点」のてこと考えると、すべてモーメントの式で解ける。半径の比＝力の逆比＝動く距離の比。

⚠ 注意：ドアノブが大きいほど（半径が大きいほど）軽い力で回せる。これは輪軸の応用。逆にドアノブを軸に近い部分でつまむと重くて回しにくい。`,
