        body: `難関中学で出題される、支点が複数あるてこや複合装置の解法を体系化しよう。

■ 2段てこ（連結したてこ）
1本目のてこの作用点が、2本目のてこの力点になっている装置。1本目で計算した力を2本目に伝えて、順番に計算していく。

例）てこAの力点に10gの力を加えると、作用点で40gの力が出る（4倍）。この40gがてこBの力点に伝わり、てこBで3倍になると、最終的に作用点で40×3 ＝ 120gの力が出る。
→ 全体で10gの力が120gになる（12倍）。連結したてこの倍率は「かけ算」になる。

■ ばねばかりとてこの複合
てこの一端をばねばかりで支える問題では、ばねばかりの示す値＝その点にかかる上向きの力。モーメントのつり合いで求める。

例）長さ60cm・重さ90gの棒の左端を支点にし、右端をばねばかりでつるす。棒の中央に120gのおもりをのせたとき、ばねばかりの読みは？
【解答】
棒の重さ90gは中央30cmに、おもり120gも中央30cmにかかる。
右端（60cm）のばねばかりの力をFとすると：
　F × 60 ＝（90 ＋ 120）× 30 ＝ 210 × 30 ＝ 6300
　F ＝ 105g

■ 支点にかかる力（支点反力）
てこ全体で「上向きの力の合計 ＝ 下向きの力の合計」が成り立つ。支点が受ける力は、この差から求められる。

例）上の問題で支点（左端）にかかる力は？
　下向き合計 ＝ 90（棒）＋ 120（おもり）＝ 210g
　上向き合計 ＝ F（ばね105g）＋ 支点の力
　支点の力 ＝ 210 ー 105 ＝ 105g（上向き）

■ 組み合わせ滑車の難問（動滑車が直列につながる）
動滑車を2個直列につないだ装置では、下の動滑車を支えるひもが上の動滑車を通り、力がさらに半分になる。ひも1本あたりの張力を段階的に追う。

★ 入試トラップ：「棒が水平でない（斜めになっている）てこ」でも、支点からの水平距離ではなく「支点からおもりまでの距離」をそのまま使う場合と、水平距離に直す場合がある。問題文の設定（ひもが鉛直か）をよく読むこと。

⚠ 注意：複合装置は必ず「力がどの順に伝わるか」を図で追う。動滑車→輪軸→てこのように、装置ごとに1段階ずつていねいに計算すれば必ず解ける。`,
