        body: `物質が水にとけて全体が均一で透明になった液を「水溶液」という。まず用語と濃度の計算を確実にしよう。

─────────────────────────────
【水溶液の用語】
溶質（ようしつ）：とけている物質（例：食塩・砂糖）
溶媒（ようばい）：とかしている液体（水溶液では水）
溶液（ようえき）：溶質＋溶媒の全体（水にとかしたもの＝水溶液）
─────────────────────────────

■ 水溶液の3つの特徴
① 透明である（色がついていてもよいが、にごっていない）
② 濃さがどこも均一（時間がたっても分離しない）
③ ろ紙でこしても溶質は取り出せない（粒が非常に小さいため）

★ 「牛乳」や「墨汁」はにごっていて光を通さないので水溶液ではない（コロイド・けんだく液）。

─────────────────────────────
【濃度（質量パーセント濃度）の公式】
　濃度（％）＝ 溶質の重さ ÷ 水溶液全体の重さ × 100
　　　　　　＝ 溶質 ÷（溶質 ＋ 水）× 100
─────────────────────────────

例1）水180gに食塩20gをとかした。この食塩水の濃度は？
　濃度 ＝ 20 ÷（20 ＋ 180）× 100 ＝ 20 ÷ 200 × 100 ＝ 10％

例2）15％の食塩水300gには食塩が何gとけているか。
　食塩 ＝ 300 × 15 ÷ 100 ＝ 45g

例3）20％の食塩水250gから水を蒸発させて、濃度を50％にしたい。何gの水を蒸発させればよいか。
　食塩の量 ＝ 250 × 0.20 ＝ 50g（蒸発させても食塩は変わらない）
　50％になったときの全体の重さ ＝ 50 ÷ 0.50 ＝ 100g
　蒸発させる水 ＝ 250 ー 100 ＝ 150g

★ ポイント：濃度計算では「分母が水溶液全体（溶質＋水）」であることに注意。「溶質÷水」ではない。ここを間違える受験生が非常に多い。

⚠ 注意：水を蒸発させても、加熱してとかす量を変えても、「溶質そのものの重さ」は変わらない。溶質の重さを固定して考えると計算がぶれない。`,
