導線に電流を流すと、導線を中心とした同心円状の磁界ができる。
・磁界の向きは「右ねじの法則」で決まる。
　右ねじが進む向き＝電流の向き、右ねじを回す向き＝磁界の向き。

例）電流を上向きに流すと、導線のまわりに反時計回り（上から見て）の磁界ができる。導線のそばに置いた方位磁針がふれることで確認できる（エルステッドの発見）。

─────────────────────────────
【コイル（導線を巻いたもの）の磁界】
導線をらせん状に巻いてコイルにし、電流を流すと、コイル全体が1つの棒磁石のようになる（N極とS極ができる）。
