        body: `コイルの中に鉄しんを入れて電流を流すと、強い磁石になる。これが電磁石で、身のまわりの多くの機械に使われている。

■ 電磁石のしくみ
コイル（導線をたくさん巻いたもの）の中に鉄しん（鉄の棒）を入れて電流を流すと、鉄しんが磁化されて非常に強い磁石になる。電流を切ると磁石のはたらきがなくなる。

─────────────────────────────
【電磁石を強くする3つの方法】
① 電流を大きくする（電池を直列に増やす）
② コイルの巻き数を多くする
③ 鉄しんを入れる（鉄しんなしより格段に強くなる）
─────────────────────────────

■ 永久磁石と電磁石の違い
　　　　　　　　永久磁石　　　　電磁石
磁力のON/OFF　できない　　　　電流でON/OFFできる
極の切りかえ　できない　　　　電流の向きで切りかえ可能
磁力の強さ　　一定　　　　　　電流・巻き数で調節できる

■ 電磁石の極
電磁石にもN極とS極がある。電流の向きを逆にすると極が入れかわる。コイルの巻く向きと電流の向きで極が決まる（右手の法則）。

■ 電磁石の利用例
・モーター（電流を回転運動に変える）
・電磁石クレーン（鉄くずを持ち上げて、電流を切って落とす）
・ベル・ブザー（電磁石で鉄片を振動させる）
・リレー・スピーカー・電磁調理器（IH）

★ ポイント：電磁石は「電流を流したときだけ磁石になる」「電流の大きさで磁力を調節できる」「電流の向きで極を変えられる」という、永久磁石にない3つの利点を持つ。だからこそ機械に広く使われる。

⚠ 注意：電磁石の巻き数を数える問題では、「同じ長さの導線を細かく巻く」と巻き数が増えて磁力が強くなる。ただし導線を長くすると抵抗が増えて電流が減り、逆に弱くなる場合もある。条件をそろえて比較することが大切。`,
