        body: `電磁石の性質を利用すると、電気を運動に変えるモーターや、運動を電気に変える発電機がつくれる。

■ モーターのしくみ
モーターは「磁石の間に置いたコイルに電流を流すと、コイルが力を受けて回転する」しくみ。
① 磁石の磁界の中にコイルを置く
② コイルに電流を流すとコイルが磁界から力を受ける
③ 整流子（せいりゅうし）で半回転ごとに電流の向きを切りかえ、同じ向きに回り続ける

■ 電流が磁界から受ける力
磁界の中に置いた導線に電流を流すと、導線は力を受けて動く。この力の向きは「電流の向き」と「磁界の向き」の両方に垂直。
・電流の向きを逆にすると力の向きも逆になる
・磁界の向きを逆にしても力の向きが逆になる
・両方逆にすると力の向きは元に戻る

─────────────────────────────
【電磁誘導（発電のしくみ）】
コイルに磁石を近づけたり遠ざけたりすると、コイルに電流が流れる。この現象を電磁誘導、流れる電流を誘導電流という。
─────────────────────────────

■ 誘導電流を大きくする方法
① 磁石を速く動かす
② 磁力の強い磁石を使う
③ コイルの巻き数を多くする

■ 誘導電流の向き
・磁石を近づけるときと遠ざけるときで、電流の向きは逆になる。
・N極を近づけるときとS極を近づけるときでも逆になる。
・磁石を止めていると（動かさないと）電流は流れない。

★ ポイント：モーターは「電気→運動」、発電機は「運動→電気」。どちらも磁石とコイルを使い、しくみは逆向きの関係になっている。手回し発電機はコイルを回して電磁誘導で発電している。

⚠ 注意：電磁誘導では「磁界が変化するとき」だけ電流が流れる。磁石をコイルの中に入れたまま静止させると、磁界が変化しないので電流は流れない。「動き（変化）」が発電のかぎ。`,
