次の4つの電磁石で、引きつける鉄のクリップの数が最も多いのはどれか。
A：電池1個・巻き数100回・鉄しんあり
B：電池2個（直列）・巻き数100回・鉄しんあり
C：電池2個（直列）・巻き数200回・鉄しんあり
D：電池2個（直列）・巻き数200回・鉄しんなし

【解答】
電磁石を強くする条件は「電流大・巻き数多・鉄しんあり」。
Cは電池2個・巻き数200回・鉄しんありで、3条件すべてが最も強い。
