        body: `難関中学・中学理科で扱う、力・電流・磁界の関係と発電のしくみを深く理解しよう。

■ フレミングの左手の法則（モーターの原理）
左手の中指・人さし指・親指を互いに垂直に開くと、
　中指＝電流の向き（Current）
　人さし指＝磁界の向き（磁石のN→S、Field）
　親指＝力の向き（導線が動く向き、Force）
この3つの関係で、磁界の中の電流が受ける力の向きが決まる。

例）磁界が右向き、電流が奥向きのとき、左手の法則にあてはめると導線は上向きの力を受ける。この力でモーターのコイルが回転する。

■ フレミングの右手の法則（発電機の原理）
発電（電磁誘導）で生じる誘導電流の向きは右手で決まる。
　親指＝導線を動かす向き
　人さし指＝磁界の向き
　中指＝生じる誘導電流の向き
モーター（左手）と発電機（右手）で使う手が違う点が重要。

■ 直流モーターの整流子のはたらき
コイルは半回転すると電流の向きが逆になり、そのままでは逆回転してしまう。整流子とブラシが半回転ごとにコイルへの電流の向きを切りかえることで、コイルが同じ向きに回り続ける。この工夫がモーターの心臓部。

■ 交流と直流
・直流（DC）：電流の向きが一定（乾電池）
・交流（AC）：電流の向きと大きさが周期的に変化する（家庭のコンセント）
　日本の交流は東日本50Hz・西日本60Hz。

■ 発電所のしくみと変圧
発電所では、タービン（水力・火力・原子力などで回す）で発電機のコイルを回し、電磁誘導で交流の電気をつくる。
・変圧器（トランス）：コイルの巻き数の比を使って電圧を変える装置。送電時は高電圧にして電力の損失を減らし、家庭では低電圧に下げて使う。交流だからこそ変圧器が使える。

★ 入試トラップ：「電磁誘導は磁界が変化するときだけ起こる」ため、変圧器も交流（変化し続ける電流）でないとはたらかない。直流を変圧器につないでも電圧は変えられない。

⚠ 注意：モーターと発電機は同じ構造で、使い方が逆。手回し発電機を2台つないで片方を回すと、もう片方がモーターとして回り出す。「電気↔運動」の変換が可逆であることを示す好例。`,
