        heading: '★ MAXレベル：燃焼の化学と消火の科学',
        body: `難関中学で問われる、燃焼をより深く理解するための発展知識を学ぼう。

■ 不完全燃焼と一酸化炭素
酸素が不足した状態で有機物が燃えると、二酸化炭素（CO₂）ではなく、有毒な一酸化炭素（CO）が発生することがある（不完全燃焼）。
　・一酸化炭素は無色・無臭で、吸うと血液中のヘモグロビンと強く結びつき、酸素を運べなくする（一酸化炭素中毒）。
　・換気の悪い部屋でガスストーブや練炭を使うと発生しやすく、事故が後を絶たない。

★ 入試トラップ：「二酸化炭素中毒」と「一酸化炭素中毒」は別物。二酸化炭素を多量に吸うと酸欠状態を招くが、一酸化炭素は微量でも血液に強く結合するため、より危険性が高い。

■ 燃焼と発熱量
物質にはそれぞれ「燃やしたときに出る熱の量（発熱量）」が決まっている。都市ガス・プロパンガス・木炭などの発熱量を比較する問題が出ることがある。単位はカロリー（cal）やジュール（J）。

■ 消火の3つの方法（燃焼の3条件との対応）
① 除去消火：燃える物を取り除く（ガスの元栓を閉じる、燃えている草を刈り取る）
② 窒息消火：酸素の供給を断つ（ふたをする、二酸化炭素消火器を使う、砂をかける）
③ 冷却消火：温度を発火点以下に下げる（水をかける）

■ 消火器の種類と仕組み
・二酸化炭素消火器：二酸化炭素を吹きつけて酸素を遮断する（窒息消火）。電気火災にも使える。
・水消火器：冷却効果が中心。ただし油や電気の火災には不向き（油は水に浮いて燃え広がる、感電の危険）。
・粉末消火器：薬剤が燃焼の連鎖反応を止める。初期消火に広く使われる。

■ 油を使った火災に水をかけてはいけない理由
油は水より密度が小さいため水に浮く。燃えている油の下に水を入れると、水が急激に水蒸気となって膨張し、燃えている油を周囲に吹き飛ばして火災が拡大する（油火災の爆発的な拡大）。天ぷら油火災は水ではなく、ぬれた布をかぶせるなどして窒息消火する。

⚠ 注意：「二酸化炭素は絶対に燃えない気体だから何でも消火できる」は誤り。反応性の高い金属（マグネシウムなど）は二酸化炭素の中でも酸素を奪って燃え続けることがある（2Mg＋CO₂→2MgO＋C）。最難関中学で扱われる例外的な発展知識として出題されることがある。`,
