        heading: '4. アンモニアの発生実験と気体の重さ',
        body: `アンモニアは強い刺激臭を持つアルカリ性の気体。集め方が特殊なので、性質とあわせて理解しよう。

─────────────────────────────
【アンモニアの発生】
　塩化アンモニウム ＋ 水酸化カルシウム（両方とも固体）を混ぜて加熱する
─────────────────────────────

■ アンモニア発生のポイント
・固体どうしの混合物を加熱する点が、酸素・二酸化炭素・水素の発生（液体を加える方法）と異なる。
・加熱する試験管の口を少し下げておく（発生した水が加熱部分に逆流して試験管が割れるのを防ぐため）。
・非常に水に溶けやすく、空気より軽いため、必ず上方置換法で集める。

■ アンモニアの性質
・無色・強い刺激臭（鼻をさす臭い）。
・水に非常によく溶け、その水溶液（アンモニア水）はアルカリ性を示す（赤色リトマス紙を青に変える）。
・噴水実験：アンモニアを満たした丸底フラスコに少量の水を入れると、アンモニアが一気に水に溶けて内部の圧力が下がり、外の水が勢いよく吸い上げられて噴水のようになる（アンモニアが水に非常によく溶ける証拠）。

─────────────────────────────
【気体の重さ（空気を1としたときの比重）】
水素：0.07　　アンモニア：0.6　　ちっ素：0.97
（空気：1.0）
酸素：1.11　　二酸化炭素：1.53
─────────────────────────────

★ ポイント：比重が1より小さい気体は空気より軽く上に集まりやすい（水素・アンモニア・ちっ素はほぼ1に近い）。比重が1より大きい気体は空気より重く下にたまりやすい（酸素・二酸化炭素）。

⚠ 注意：ちっ素の比重は0.97で空気（1.0）とほとんど同じであるため、実験で集め方を選ぶ判断材料としてはあまり使われない。ちっ素は反応しにくく発生実験自体が入試ではあまり出題されない点も覚えておこう。`,
