        body: `難関中学で問われる、動物の進化と体のつくりの関係を発展的に理解しよう。

■ 相同器官と収れん進化
・相同器官：起源（もとになったつくり）が同じで、はたらきが異なる器官。ヒトの腕・コウモリの翼・クジラのひれ・ウマの前あしは、骨の基本構造が同じで、共通の祖先から進化したと考えられる。
・収れん進化：起源が異なる生物が、似た環境に適応した結果、似た体のつくりを独立に進化させること。（例：魚のひれとイルカのひれは起源が違うが形が似ている）

■ 中間的な特徴を持つ生物
・シーラカンス：魚類だがひれの骨格が両生類の四肢に似た構造を持ち、魚類から両生類への進化を考える手がかりとされる「生きた化石」。
・カモノハシ：ほ乳類だが卵を産む（卵生）という、は虫類的な特徴を残す原始的なほ乳類。

★ ポイント：カモノハシは「乳で子を育てる（ほ乳類の条件）」ため分類上はほ乳類だが、卵生という珍しい特徴を持つ。「ほ乳類＝必ず胎生」という思い込みへの入試トラップとしてよく使われる。

■ 擬態と保護色
・擬態：他の生物や周囲のものに姿を似せて身を守る、または獲物に気づかれにくくする。（例：ナナフシは枝そっくりの姿、ハナカマキリは花に擬態）
・保護色：周囲の環境の色に体色を合わせて敵に見つかりにくくする。（例：バッタの緑色、雪原のホッキョクギツネの白い毛）

■ 生存競争と自然選択（進化のしくみの基礎）
同じ種の中でも個体ごとにわずかな違い（変異）があり、環境に適した特徴を持つ個体が生き残り子孫を残しやすい。これを自然選択（自然淘汰）といい、長い年月をかけて種が変化していく進化のしくみの土台となる。

⚠ 注意：「進化」は個体が一生の間に変化することではなく、世代を重ねる中で集団の特徴が変わっていく現象。キリンの首が「一生懸命伸ばしたから伸びた」という説明（用不用説）は現在では否定されており、首の長い個体が生存に有利で子孫を残しやすかった、という自然選択の考え方が現在の進化論の基本である。`,
