        body: `冬になると多くの生き物が活動を止め、冬を越すための特別な姿になる。冬越しの方法を動物のグループごとに整理しよう。

─────────────────────────────
【冬越しの姿（昆虫の例）】
卵で冬越し：カマキリ・オオカマキリ（泡状のかたまりの中に卵を産む）
幼虫で冬越し：カブトムシ（土の中で幼虫のまま冬を越す）
さなぎで冬越し：アゲハチョウ（さなぎの姿でじっとして春を待つ）
成虫で冬越し：テントウムシ（集団で物かげに集まって冬を越す）
─────────────────────────────

■ 変温動物の冬眠
カエル・ヘビ・トカゲなどの変温動物は、気温が下がると体温も下がり、体を動かすためのエネルギーをつくれなくなる。そのため、土の中や落ち葉の下などにもぐり、じっと動かずに春を待つ（冬眠）。

■ 恒温動物の冬眠（クマの例）
クマは恒温動物だが、冬になるとえさが少なくなるため、秋のうちにたくさん食べて脂肪をたくわえ、冬の間は洞窟などで眠ったように過ごしてエネルギーの消費を抑える（クマの冬眠は体温がわずかしか下がらず、変温動物の冬眠とはしくみが異なる）。

■ 冬眠中の呼吸・心拍数の変化
冬眠中の動物は、呼吸数・心拍数が大きく減少し、体温も下がることでエネルギーの消費を最小限に抑えている。春になって気温が上がると、体温が上がり活動を再開する。

★ ポイント：変温動物の冬眠は「体温が外気温と同じくらいまで下がる」のに対し、クマ（恒温動物）の冬眠は「体温はあまり下がらないが、代謝を大きく落として省エネする」という違いがある。両者を「同じ冬眠」と一括りにしないこと。

⚠ 注意：すべての動物が冬眠するわけではない。ウサギ・シカなど多くのほ乳類は冬眠せず、冬の間も食物を探して活動を続ける（毛が生え変わって保温性を高めるなどの適応で寒さに耐える）。`,
