        body: `難関中学で出題される、気温の積み重ねと生き物の成長・行動の関係を発展的に学ぼう。

■ 生物季節学（フェノロジー）とは
気温や日照時間などの環境変化と、生物の活動時期（開花・発芽・渡り・冬眠からの目覚めなど）の関係を研究する分野。気象庁は長年、サクラの開花日やセミの初鳴き日などを観測記録している。

■ サクラの開花予想と「積算温度」の考え方
サクラのつぼみは、休眠から目覚めたあと、気温が高い日が続くほど早く開花に近づく。この「暖かさの積み重ね」を数値化したものを積算温度という。
　例）ある地域で、2月1日以降の日平均気温を毎日足し合わせていき、合計がある一定の値（地域によって異なる目安）を超えるとサクラが開花すると予測されている。
　　　　1日目5℃、2日目7℃、3日目8℃… と足し合わせていく計算方法をイメージするとよい。

■ 昆虫の発育と温度の関係（発育零点）
昆虫の成長速度も気温に強く影響される。ある温度（発育零点）以下では成長が止まり、それより高い気温が続くほど早く育つ。農業では、害虫の発生時期をこの積算温度から予測して、対策のタイミングを判断することがある。

■ 地球温暖化と生物季節の変化
近年、サクラの開花日が早まる傾向や、セミの初鳴きの時期が変わる傾向が観測されており、地球温暖化との関連が指摘されている。渡り鳥の飛来時期のずれや、昆虫の分布域が北へ広がる現象なども報告されている。

★ 入試トラップ：「気温が高ければ高いほど生き物は必ず速く育つ」は誤り。多くの生物には成長に適した温度範囲があり、高温になりすぎるとかえって成長が妨げられたり、生存できなくなったりする（発育の上限温度が存在する）。

⚠ 注意：生物季節の変化は、単に「暖かくなった」だけでなく、生態系内の他の生物（えさ・天敵・受粉相手の植物）との時期のずれ（フェノロジカル・ミスマッチ）を引き起こし、生態系全体に影響することがある発展的な視点として覚えておこう。`,
