        body: `おしべの花粉がめしべの柱頭につくことを「受粉」という。受粉のしかたにはいくつかのタイプがある。

■ 受粉から種子ができるまでの流れ
① おしべのやくから出た花粉が、めしべの柱頭につく（受粉）
② 柱頭についた花粉から「花粉管」がのび、子房の中の胚珠に向かって伸びていく
③ 花粉管の中を通って精細胞が胚珠まで届き、受精が起こる
④ 受精後、胚珠は種子に、子房は果実に育つ

─────────────────────────────
【自家受粉と他家受粉】
自家受粉：同じ花、または同じ株の中で受粉すること（例：エンドウ・イネの多くは自家受粉）
他家受粉：別の株の花の花粉で受粉すること（例：多くの虫媒花・風媒花）
─────────────────────────────

■ 他家受粉を促すしくみ
多くの植物は、同じ花の中でおしべとめしべが成熟する時期をずらす（雄性先熟・雌性先熟）ことで、自分の花粉で受粉するのを避け、他の株との受粉（他家受粉）を促している。これにより、遺伝的な多様性が生まれ、環境変化への適応力が高まると考えられている。

■ 自家受粉のメリット・デメリット
・メリット：確実に種子を残せる（虫や風がいなくても受粉できる）。
・デメリット：遺伝的な多様性が生まれにくく、環境の変化に弱くなりやすい。

例）メンデルがエンドウを実験に使ったのは、エンドウが自家受粉する性質を持ち、純系（同じ遺伝子型がくり返し伝わる系統）をつくりやすかったためである。

★ ポイント：受粉と受精は別のことば。「受粉」は花粉が柱頭につくこと（外側の出来事）、「受精」は花粉管を通って精細胞が胚珠に届き合体すること（内部の出来事）。この違いを問う問題が頻出。

⚠ 注意：受粉してもすぐに種子ができるわけではなく、花粉管が胚珠まで届いて受精が起こって初めて種子のもとができる。受粉と受精の間には時間差がある。`,
