        heading: '3. 虫媒花と風媒花',
        body: `植物が花粉を運ぶ方法には、大きく分けて「虫に運んでもらう」ものと「風で飛ばす」ものがある。それぞれの花の特徴を対比して理解しよう。

─────────────────────────────
【虫媒花と風媒花の比較】
　　　　　　虫媒花　　　　　　　　風媒花
花びら　　　目立つ・色があざやか　目立たない・小さい、またはない
香り・蜜　　多くが持つ　　　　　　持たないことが多い
花粉の量　　少ない　　　　　　　　非常に多い
花粉の重さ　やや重くねばりけがある 軽くてサラサラ
代表例　　　アブラナ・サクラ・アサガオ イネ・トウモロコシ・スギ・マツ
─────────────────────────────

■ 虫媒花のしくみ
虫媒花は、目立つ花びら・甘い蜜・よい香りで虫（ハチ・チョウなど）を呼び寄せる。虫が蜜を吸うときに体に花粉がつき、次の花に移動したときにその花粉が柱頭につく（受粉）。虫という「運び手」がいるため、花粉は少量でも効率よく受粉できる。

■ 風媒花のしくみ
風媒花は、風にまかせて花粉を飛ばすため、どこに届くかわからない。そのぶん、受粉の成功率を上げるために非常に大量の花粉をつくる。花びらは目立つ必要がないため小さいか、ないことが多い。

例）スギ花粉症は、風媒花であるスギが大量の花粉を風で飛ばすことによって起こる。虫媒花の花粉は粒が大きくねばりけがあり風に乗りにくいため、花粉症の原因になりにくい。

■ 花粉の数の違い（イメージ）
虫媒花（アブラナなど）は1つの花で数千個程度の花粉をつくるのに対し、風媒花（イネ科など）は同程度の花で数万〜数十万個もの花粉をつくることがある。これは「運び手がいない不確実さ」を「数の多さ」で補っていると考えられる。

★ ポイント：「花びらが目立つ・においがする＝虫媒花」「花びらが目立たず、花粉症の原因になりやすい＝風媒花」という対応をセットで覚える。

⚠ 注意：水を利用して花粉を運ぶ「水媒花」（例：クロモなどの水草）や、鳥が花粉を運ぶ「鳥媒花」（例：ツバキ）も存在する。中学入試では虫媒花・風媒花が中心だが、発展として例外があることも知っておこう。`,
