        body: `受精が終わると、花の各部分が変化して果実と種子ができる。植物を「被子植物」と「裸子植物」に分ける違いも確認しよう。

■ 果実と種子ができるまで
　子房 → 果実（果肉・果皮になる部分）
　胚珠 → 種子（中に「胚」＝将来の芽・根・葉のもとが入っている）

例）リンゴやモモの「食べる部分（果肉）」は子房が育ったもの、中の「種」が胚珠から育った種子である。

■ 種子の中の養分
種子の中には、発芽して成長するための栄養分がたくわえられている。
・有胚乳種子：胚のまわりに「胚乳」という栄養分の部分がある（例：イネ・トウモロコシ・カキ）
・無胚乳種子：胚乳がなく、子葉（しよう）に直接栄養がたくわえられている（例：アサガオ・エンドウ・クリ）

─────────────────────────────
【被子植物と裸子植物】
被子植物：胚珠が子房に包まれている → 受精後に果実ができる（アブラナ・サクラ・イネなど、ほとんどの花をつける植物）
裸子植物：胚珠がむき出しで子房がない → 果実ができない（マツ・スギ・イチョウ・ソテツ）
─────────────────────────────

■ 裸子植物の花のつくり
マツには「雄花（花粉をつくる）」と「雌花（胚珠がついている）」の2種類の花があり、どちらも花びら・がくを持たない簡単なつくりをしている。イチョウの「ぎんなん」は種子であり、果実ではない（種子の外側の皮が果実のように見えるが、子房が育ったものではない）。

★ ポイント：「マツかさ（松ぼっくり）」はマツの雌花が育ったもので、種子はできるが果実はできない（裸子植物には果実がない）。「イチョウのぎんなんは果実」という誤解は入試の頻出トラップ。

⚠ 注意：被子植物の中には、子房が発達せず果実らしい果実をつくらないように見える植物（イネなど）もあるが、分類上はれっきとした被子植物である。「果実が目立つかどうか」ではなく「胚珠が子房に包まれているかどうか」で判断する。`,
