        body: `肺の中には「肺胞（はいほう）」という非常に小さな袋状の構造が無数に存在し、効率的なガス交換を可能にしている。

■ 肺胞のつくり
気管は枝分かれをくり返して細い気管支となり、その先端に「肺胞」という小さな袋がぶどうの房のようにたくさんついている。片方の肺だけで肺胞は数億個にもなるといわれる。

■ 肺胞が無数にある理由（表面積の拡大）
肺胞が1つの大きな袋ではなく、無数の小さな袋に分かれていることで、肺全体の表面積が非常に大きくなる（成人でテニスコート半面ほどの面積になるといわれる）。表面積が大きいほど、酸素と二酸化炭素をやり取りできる場所が増え、ガス交換の効率が上がる。

■ ガス交換のしくみ
肺胞のまわりは非常に細い毛細血管が網の目のように取り巻いている。
　・肺胞の中の空気に多い酸素 → 濃度の高い方から低い方へ移動する性質（拡散）により、血液（毛細血管）の中に入る
　・血液の中に多い二酸化炭素 → 同様に拡散により、肺胞の中の空気側へ出ていく
このガス交換によって、静脈血（酸素が少ない）が動脈血（酸素が多い）に変わる。

★ ポイント：「肺胞が無数にある」ことの意味は、必ず「表面積を大きくしてガス交換の効率を上げるため」と説明できるようにしておく。これは小腸の柔毛が無数にあることと同じ考え方（表面積を増やして効率を上げる）で、入試では両者を対応させて問われることがある。

⚠ 注意：肺胞で行われるのは「拡散」による受け渡しであり、心臓のようにポンプの力で押し出しているわけではない。酸素・二酸化炭素はそれぞれ「濃度の高い方から低い方へ」自然に移動する点を理解しておくこと。`,
