        heading: '3. 血液の成分とはたらき',
        body: `血液は液体の成分と固体（細胞）の成分からなる。それぞれの成分のはたらきを正確に区別しよう。

─────────────────────────────
【血液の成分とはたらき】
赤血球：酸素を運ぶ。中にヘモグロビンという赤い色素を含み、酸素の多いところで酸素と結びつき、少ないところで酸素を放す
白血球：体に入った細菌やウイルスを分解する（免疫のはたらき）
血小板：出血したときに血液を固めて傷口をふさぐ（血液凝固）
血しょう：血液の液体成分。栄養分・不要物（老廃物）・二酸化炭素などを溶かして運ぶ
─────────────────────────────

■ ヘモグロビンのはたらき
ヘモグロビンは酸素の多い場所（肺）で酸素と結びつき（酸素ヘモグロビンになる）、酸素の少ない場所（全身の細胞）で酸素を放す性質を持つ。この性質のおかげで、肺で受け取った酸素を全身の細胞まで確実に届けることができる。

■ 血液の色の違い
・動脈血（酸素が多い）：ヘモグロビンが酸素と結びついているため鮮やかな赤色
・静脈血（酸素が少ない）：酸素を放したヘモグロビンが多いため、やや暗い赤色

■ 白血球と免疫
白血球には複数の種類があり、体内に侵入した細菌やウイルスを取りこんで分解したり、抗体をつくって攻撃したりする。けがをした部分が赤く腫れる（炎症）のは、白血球が集まって細菌と戦っているためでもある。

■ 血しょうと組織液
血しょうの一部は毛細血管のかべからしみ出して細胞のまわりを満たし、「組織液」となって細胞に栄養や酸素を渡し、老廃物を受け取る仲立ちをしている。

★ ポイント：血液の4つの成分（赤血球・白血球・血小板・血しょう）とそのはたらきは、必ずセットで、かつ混同せずに覚えること。「酸素を運ぶのは赤血球」「細菌と戦うのは白血球」「血を固めるのは血小板」「栄養や老廃物を運ぶのは血しょう」と役割ごとに整理する。

⚠ 注意：赤血球には核がない（成熟する過程で核を失う）という特徴があるが、白血球には核がある。この違いを顕微鏡観察の記述問題で問われることがある。`,
