        heading: '★ MAXレベル：対物ミクロメーターと実際の大きさの計算',
        body: `難関中学で出題される、顕微鏡で観察したものの実際の大きさを求める計算を攻略しよう。

■ 接眼ミクロメーターと対物ミクロメーター
・接眼ミクロメーター：接眼レンズの中に入れる、目盛りだけが刻まれた小さなガラス板。倍率を変えても見かけの目盛りの数は変わらない。
・対物ミクロメーター：1目盛りが正確に0.01mm（10μm）であることがわかっている、実際の長さの基準となるガラス板。

■ 実際の大きさを求める手順
① 対物ミクロメーターをステージにのせ、接眼ミクロメーターの目盛りと重ねて、「接眼ミクロメーターの何目盛り分が対物ミクロメーターの何目盛り分にあたるか」を記録する
② 対物ミクロメーターを外し、観察したいプレパラートに戻す（このとき倍率は変えない）
③ 観察物が接眼ミクロメーターの目盛りで何目盛り分の大きさかを読む
④ ①で求めた対応関係を使って、観察物の実際の大きさ（mm）を計算する

例）ある倍率で観察したとき、接眼ミクロメーター10目盛りが対物ミクロメーター4目盛り（1目盛り0.01mm）と一致した。このとき接眼ミクロメーターの1目盛りの実際の長さは何mmか。
【解答】
対物ミクロメーター4目盛り分の長さ ＝ 4 × 0.01 ＝ 0.04mm
これが接眼ミクロメーター10目盛り分にあたるので、
接眼ミクロメーター1目盛り ＝ 0.04 ÷ 10 ＝ 0.004mm

この後、観察物が接眼ミクロメーターで何目盛り分かがわかれば、「0.004mm × 目盛り数」で実際の大きさが計算できる。

■ 倍率を変えたときの注意
倍率を変えると、接眼ミクロメーターの1目盛りが表す実際の長さも変わる（倍率が高いほど、1目盛りが表す実際の長さは小さくなる）。そのため、倍率を変えるたびに、対物ミクロメーターとの対応関係を測定し直す必要がある。

★ 入試トラップ：「接眼ミクロメーターの目盛りの間隔は倍率を変えても一定に見える」が、それが表す「実際の長さ」は倍率によって変わる、という点を混同しないこと。見た目の目盛り幅と、それが示す実際の距離は別物である。

⚠ 注意：この計算は手順が多いため、「まず対物ミクロメーターで基準（1目盛りの実際の長さ）を求める」→「その基準を使って観察物の実際の大きさを求める」という2段階の流れを意識して、慌てずに順番通り計算することが正答への近道。`,
