        body: `「生物多様性」とは、地球上にさまざまな生き物が存在し、それぞれが関わり合って生態系を成り立たせていることを指す言葉である。3つのレベルに分けて理解しよう。

─────────────────────────────
【生物多様性の3つのレベル】
① 種の多様性：さまざまな種類の生き物が存在すること（例：森に多くの種類の昆虫・植物・鳥がいる）
② 遺伝的多様性：同じ種の中でも個体ごとに遺伝子（形質）に違いがあること（例：同じ種のイネでも品種によって異なる特徴を持つ）
③ 生態系の多様性：森林・湿原・干潟・サンゴ礁など、さまざまなタイプの環境（生態系）が存在すること
─────────────────────────────

■ なぜ生物多様性が大切なのか
・食物網が複雑であるほど、1種類の生物が減っても他の種がその役割を補いやすく、生態系全体が安定しやすい（生態系の回復力・レジリエンス）。
・遺伝的多様性が高いほど、病気や環境の変化があったときに、その中の一部の個体が生き残れる可能性が高くなる。
・多様な生態系があることで、それぞれの環境に適応した多様な生物が存在できる。

例）同じ品種だけを一面に栽培した畑では、その品種が弱い病気が流行すると全滅する危険があるが、複数の品種を育てていれば、病気に強い品種が生き残る可能性がある。これは遺伝的多様性の重要性を示す例。

★ ポイント：「生物多様性＝生き物の数が多いこと」ではなく、「多様なレベル（種・遺伝子・生態系）で多様さが保たれていること」を意味する。この3つのレベルを区別して説明できることが記述問題での得点につながる。

⚠ 注意：外来生物が増えて「生き物の数」が一時的に増えても、それは在来の生物多様性を脅かしている場合が多く、「数が多い＝多様性が高い」とは限らない点に注意。`,
