        body: `自然界には、分解されにくい物質が食物連鎖を通じて生物の体内に蓄積されていく「生物濃縮」という現象がある。

■ 生物濃縮とは
体内で分解されにくい・排出されにくい物質（一部の農薬・重金属など）が、食物連鎖を通じて上位の生物（捕食者）になるほど、体内によりいっそう高い濃度で蓄積されていく現象。

─────────────────────────────
【生物濃縮のしくみ（イメージ）】
水中のプランクトン（低濃度で物質を取りこむ）
　→ それを食べる小魚（プランクトンを大量に食べるため濃度が上がる）
　→ それを食べる大型の魚（小魚を大量に食べるためさらに濃度が上がる）
　→ それを食べる鳥や人間（もっとも高い濃度になる）
─────────────────────────────

■ 生物濃縮が起こる理由
栄養段階が1つ上がるごとに、下位の生物を大量に食べて自分の体をつくる必要がある（生態ピラミッドで上位ほど個体数・総重量が少なくなることに対応）。分解・排出されにくい物質は、食べられた分だけ捕食者の体内にそのまま積み重なっていくため、上位の生物ほど濃度が高くなる。

■ 過去に問題となった生物濃縮の例
・DDT（農薬）：かつて広く使われていたが、生物濃縮によって猛禽類（タカ・ワシなど）の卵の殻を薄くし、繁殖に悪影響を与えたことが知られ、多くの国で使用が禁止された。
・水俣病：工場から排出されたメチル水銀が海の生物に蓄積し、それを大量に食べた人に深刻な健康被害を引き起こした、日本の公害の代表例。

★ ポイント：生物濃縮は「上位の生物ほど高濃度になる」という生態ピラミッドと同じ向きの関係。汚染物質の量そのものは少なくても、食物連鎖を通じて濃縮され、頂点にいる生物（人間をふくむ）に深刻な影響を与えることがある。

⚠ 注意：すべての物質が生物濃縮を起こすわけではない。水に溶けやすく体外に排出されやすい物質は蓄積しにくく、脂肪に溶けやすく分解されにくい物質ほど生物濃縮を起こしやすい。`,
