        heading: '1. マグマの粘性と噴火の様式・火山の形',
        body: `火山の噴火のしかたや形は、地下にあるマグマの「ねばりけ（粘性）」によって大きく変わる。この関係を正確に理解しよう。

─────────────────────────────
【マグマの粘性と噴火・火山の形の関係】
粘性が小さい（さらさら）→ おだやかな噴火（溶岩が流れ出る）→ なだらかな盾状火山
粘性が中くらい　　　　　→ 中程度の噴火（溶岩流と噴石が混じる）→ 円すい形の成層火山
粘性が大きい（ねばねば）→ 爆発的な噴火（ガスが抜けにくく圧力がたまる）→ 盛り上がった溶岩ドーム
─────────────────────────────

■ 盾状火山（たてじょうかざん）
粘性の小さいマグマが噴出してできる、傾斜がゆるやかで広がった形の火山。溶岩がさらさらと遠くまで流れるため、なだらかな形になる。
　例）ハワイ島のマウナロア・キラウエア

■ 成層火山（せいそうかざん）
溶岩の流出と、火山灰・軽石などの噴出（爆発的な噴火）を繰り返すことで、地層が積み重なるようにできる円すい形の火山。日本の多くの火山がこのタイプ。
　例）富士山・桜島

■ 溶岩ドーム（ようがんドーム）
粘性が非常に大きいマグマは流れにくく、火口付近に盛り上がってドーム状に固まる。爆発的な噴火をともなうことが多く、火砕流の原因になりやすい。
　例）昭和新山・雲仙普賢岳の溶岩ドーム

★ ポイント：「ねばりけが強いマグマ＝爆発的で危険」「ねばりけが弱いマグマ＝おだやかで溶岩がゆっくり流れる」という対応を、火山の形とセットで覚える。

⚠ 注意：「おだやかな噴火＝安全」というわけではない。盾状火山でも溶岩の流出速度が非常に速い場合があり、粘性が小さいマグマの噴火にもそれぞれの危険性がある。`,
